const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to await evaluate/getInfo
  const eva = (obj) =>
    new Promise((resolve, reject) => obj.getInfo((res, err) => (err ? reject(err) : resolve(res))));
  try {
    // 1) Geometry: Southern Ethiopia ≈ Ethiopia ∩ [32E,48E, 2N,7.5N]
    const eth = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Ethiopia'))
      .first()
      .geometry();
    const southRect = ee.Geometry.Rectangle([32, 2, 48, 7.5], null, false);
    let southEth = eth.intersection(southRect, ee.ErrorMargin(1));
    southEth = southEth.simplify(2000); // simplify for performance

    const southAreaKm2 = ee.Number(southEth.area(1)).divide(1e6);
    const areaKm2 = await eva(southAreaKm2);
    console.log(`Region: Southern Ethiopia approx. Area: ${areaKm2.toFixed(0)} km²`);

    // 2) Data: CHIRPS Daily precipitation (mm/day)
    const colId = 'UCSB-CHG/CHIRPS/DAILY';
    // 2021 Oct-Nov
    let col2021 = ee.ImageCollection(colId)
      .filterDate('2021-10-01', '2021-12-01')
      .filterBounds(southEth);
    let n2021 = await eva(col2021.size());
    if (n2021 === 0) {
      col2021 = ee.ImageCollection(colId).filterDate('2021-10-01', '2021-12-01'); // fallback without bounds
      n2021 = await eva(col2021.size());
    }
    console.log(`2021 Oct-Nov Images: ${n2021}`);
    if (n2021 === 0) {
      console.log('C1: Empty Collection');
      return;
    }
    const img2021 = col2021.select('precipitation').sum();

    // Baseline 2000-2013 Oct-Nov average
    let colBase = ee.ImageCollection(colId)
      .filterDate('2000-01-01', '2013-12-31')
      .filterBounds(southEth)
      .filter(ee.Filter.calendarRange(10, 11, 'month'));
    let nBase = await eva(colBase.size());
    if (nBase === 0) {
      colBase = ee.ImageCollection(colId)
        .filterDate('2000-01-01', '2013-12-31')
        .filter(ee.Filter.calendarRange(10, 11, 'month')); // fallback without bounds
      nBase = await eva(colBase.size());
    }
    console.log(`Baseline (2000-2013) Oct-Nov Images: ${nBase}`);
    if (nBase === 0) {
      console.log('C1: Empty Collection');
      return;
    }
    const yearsCount = 14; // 2000..2013 inclusive
    const baseSum = colBase.select('precipitation').sum();
    const baseMeanImg = baseSum.divide(yearsCount).rename('precipitation');

    // 3) Reduce over region
    const scale = 5000;
    const stats2021 = await eva(
      img2021.reduceRegion({
        reducer: ee.Reducer.combine({
          reducer1: ee.Reducer.mean(),
          reducer2: ee.Reducer.count(),
          sharedInputs: true,
        }),
        geometry: southEth,
        scale: scale,
        maxPixels: 1e9,
      })
    );
    const statsBase = await eva(
      baseMeanImg.reduceRegion({
        reducer: ee.Reducer.combine({
          reducer1: ee.Reducer.mean(),
          reducer2: ee.Reducer.count(),
          sharedInputs: true,
        }),
        geometry: southEth,
        scale: scale,
        maxPixels: 1e9,
      })
    );

    const mean2021 = stats2021.precipitation_mean;
    const cnt2021 = stats2021.precipitation_count || 0;
    const meanBase = statsBase.precipitation_mean;
    const cntBase = statsBase.precipitation_count || 0;

    if (!cnt2021 || !cntBase) {
      console.log('C2: No Valid Pixels');
      return;
    }
    if (
      mean2021 === null ||
      meanBase === null ||
      isNaN(mean2021) ||
      isNaN(meanBase)
    ) {
      console.log('C3: Calculation Failure');
      return;
    }

    // 4) Report concise evidence
    // Units: mm (sum over the 2 months for 2021; baseline is average of Oct-Nov sums across 2000-2013)
    console.log(`Valid Pixels -> 2021: ${cnt2021}, Baseline: ${cntBase}`);
    console.log(`2021 Oct-Nov total (area-mean): ${mean2021.toFixed(1)} mm`);
    console.log(`Baseline Oct-Nov avg (2000-2013, area-mean): ${meanBase.toFixed(1)} mm`);
    const diff = mean2021 - meanBase;
    const pct = meanBase !== 0 ? (diff / meanBase) * 100 : null;
    console.log(`Difference (2021 - baseline): ${diff.toFixed(1)} mm`);
    if (pct !== null && isFinite(pct)) {
      console.log(`Percent difference: ${pct.toFixed(1)}%`);
    } else {
      console.log('Percent difference: n/a (baseline ~ 0)');
    }

    // 5) Final Answer
    // A: Yes (less than baseline) / B: No (not less)
    const isLess = mean2021 < meanBase;
    console.log(isLess ? 'A: Yes' : 'B: No');
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
